select 'cartes resolues toujours en base' as controle,
       (select count(*) from v5_apercu_gardees g join public.prompts p on p.id = g.id) as trouvees,
       601 as attendues;

select 'visuels sur les cartes gardees' as controle,
       (select count(*) from public.prompt_media m join v5_apercu_gardees g on g.id = m.prompt_id) as fichiers;

select 'visuels sur les cartes retirees' as controle,
       (select count(*) from public.prompt_media m join v5_apercu_retirees r on r.id = m.prompt_id) as fichiers;

select p.status as statut_actuel, count(*) as cartes
from v5_apercu_retirees r join public.prompts p on p.id = r.id group by 1 order by 1;

do $ctrl$
begin
  if not ((select count(*) from v5_apercu_gardees g join public.prompts p on p.id = g.id) = 601) then
    raise exception 'Lot 000 : une carte resolue a disparu de la base depuis l''extraction. Relancer extract-catalogue-v5.py avant d''importer.';
  end if;
end $ctrl$;

do $ctrl$
begin
  if not ((select count(*) from public.prompt_media m join v5_apercu_retirees r on r.id = m.prompt_id) = 0) then
    raise exception 'Lot 000 : un retrait emporterait un visuel. La refonte ne doit retirer que des cartes sans media.';
  end if;
end $ctrl$;

commit;
